const RELEASE='2.3.0'
const RELEASE_KEY='abyssal-descent-release-session'
async function clearStaleWorker(){try{if(!('serviceWorker' in navigator)||!navigator.serviceWorker.controller)return false;if(sessionStorage.getItem(RELEASE_KEY)===RELEASE)return false;sessionStorage.setItem(RELEASE_KEY,RELEASE);const regs=await navigator.serviceWorker.getRegistrations();await Promise.all(regs.map(r=>r.unregister()));if('caches'in window){const keys=await caches.keys();await Promise.all(keys.filter(k=>k.startsWith('abyssal-descent-')).map(k=>caches.delete(k)))}location.reload();return true}catch{return false}}
function fatal(error){const root=document.getElementById('root')||document.body;root.innerHTML=`<section class="boot-error"><h1>Runtime bootstrap error</h1><p>The game could not load. Reload once to clear the previous release cache.</p><code>${String(error?.stack||error?.message||error).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}</code></section>`}
try{if(!(await clearStaleWorker())){await import('./main.js?v=2.3.0');if(!window.__abyssal)throw new Error('Core runtime did not initialize');await import('./v12.js?v=2.3.0');if(!window.__abyssalV12)throw new Error('PWA/Codex layer did not initialize');await import('./v13.js?v=2.3.0');if(!window.__abyssalV13)throw new Error('Daily/Options layer did not initialize');await import('./v14.js?v=2.3.0');if(!window.__abyssalV14)throw new Error('Presentation layer did not initialize');await import('./v23-c64.js?v=2.3.0');if(!window.__abyssalV23)throw new Error('C64 renderer did not initialize')}}catch(error){console.error('[Abyssal bootstrap]',error);fatal(error)}
